public record SplitInheritancePlan(List<ChildPlan> children) {}
public record ChildPlan(String batchKey, BigDecimal targetMass, List<BigDecimal> shares) {}

public Optional<SplitInheritancePlan> prepareSplitInheritance(String parentKey, List<SplitRequest.ChildSpec> children) {
    Optional<BindingRow> binding = recipes.findBinding(parentKey);
    if (binding.isEmpty()) {
        for (child : children) if (child.targetMassGrams() != null) throw badRequest("父批未绑定配方，子批不应提供目标质量");
        return Optional.empty();
    }
    BindingRow b = binding.get();
    BigDecimal parentTarget = new BigDecimal(b.targetMass());
    List<IngredientRow> ingredients = recipes.findIngredients(b.recipeKey());
    Map<String,BigDecimal> totals = validTotals(parentKey, ingredients);
    BigDecimal sum = ZERO;
    for (child : children) {
        BigDecimal m = child.targetMassGrams();
        if (m == null) throw badRequest("子批必须提供目标质量 targetMassGrams");
        if (m.signum() <= 0) throw badRequest("子批目标质量必须为正值");
        if (m.scale() > 6) throw badRequest("子批目标质量最多 6 位小数");
        sum = sum.add(m);
    }
    if (sum.compareTo(parentTarget) != 0) throw unprocessable("子批目标质量之和不等于父批目标质量，无法守恒");
    List<ChildPlan> plans = new ArrayList<>();
    for (child : children) {
        List<BigDecimal> shares = new ArrayList<>();
        for (ing : ingredients) {
            BigDecimal share;
            try {
                share = totals.get(ing).multiply(child.targetMassGrams()).divide(parentTarget, 6, RoundingMode.UNNECESSARY);
            } catch (ArithmeticException e) {
                throw unprocessable("成分 " + ing + " 按子批质量比例无法在 6 位小数内精确继承，拆分不守恒");
            }
            shares.add(share);
        }
        plans.add(new ChildPlan(child.batchKey(), child.targetMassGrams(), shares));
    }
    return Optional.of(new SplitInheritancePlan(plans));
}

public void applySplitInheritance(String parentKey, SplitInheritancePlan plan, String now) {
    BindingRow b = recipes.findBinding(parentKey).orElseThrow();
    List<IngredientRow> ingredients = ...;
    for (childPlan : plan.children()) {
        recipes.insertBinding(new BindingRow(0, childPlan.batchKey(), b.recipeKey(), childPlan.targetMass().toString(), "SYSTEM", now));
        int version = 0;
        for (i...) {
            version++;
            recipes.insertWeighing(new WeighingRow(0, childKey, ingredients.get(i).ingredient(), shares.get(i).toString(), KIND_INHERIT, null, null, "SYSTEM", version, now));
        }
    }
}
```

