            for (int i = 0; i < specs.size(); i++) {
                recipes.insertIngredient(req.recipeKey(), names.get(i),
                        specs.get(i).percentage().toString(), i + 1);
                views.add(new RecipeResponse.IngredientView(names.get(i), specs.get(i).percentage()));
            }
